async function api(path,body={}){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const raw=await r.text();let v;try{v=JSON.parse(raw)}catch{v={error:r.status===413?'Attachment upload is too large for the relay':'Could not reach the messaging service ('+r.status+')'}}if(!r.ok){const error=new Error(v.error);error.status=r.status;throw error;}return v}
async function derive(password,salt){const k=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:un64(salt),iterations:600000,hash:'SHA-256'},k,{name:'AES-GCM',length:256},true,['encrypt','decrypt'])}
