const vaultDatabase=new Promise((resolve,reject)=>{const req=indexedDB.open('only-yours-private',1);req.onupgradeneeded=()=>req.result.createObjectStore('vault');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
async function readVault(){const db=await vaultDatabase;return new Promise((resolve,reject)=>{const r=db.transaction('vault').objectStore('vault').get('sealed');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
