function fileLink(m,keepsake=false){const wrap=el('div',null,'media-item'),media=/^(image\/(png|jpeg|webp|gif)|video\/(mp4|webm))$/.test(m.file.type);const a=el('button',m.file.type.startsWith('audio/')?'▶ Voice message':m.file.name,'media-preview');a.type='button';a.onclick=()=>m.file.type.startsWith('audio/')?voicePlayer.open(new Blob([un64(m.file.data)],{type:m.file.type})):media?showMedia(m.file,{id:m.id}):exportFile(m.file);if(/^image\/(png|jpeg|webp|gif)$/.test(m.file.type)){let cached=mediaURLs.get(m.id);if(!cached||cached.data!==m.file.data){if(cached)URL.revokeObjectURL(cached.url);cached={data:m.file.data,url:URL.createObjectURL(new Blob([un64(m.file.data)],{type:m.file.type}))};mediaURLs.set(m.id,cached)}const u=cached.url;const img=el('img');img.src=u;img.alt=m.file.name;a.prepend(img)}wrap.append(a);if(keepsake){const remove=el('button','Delete from this device','delete-keepsake');remove.type='button';remove.onclick=()=>requestLocalDelete([m.id]);wrap.append(remove)}return wrap}

function prune(){if(!vault)return false;const now=Date.now(),before=vault.messages.length;const expired=new Set(vault.messages.filter(m=>m.expires&&m.expires<=now).map(m=>m.id));if($('#viewer').open&&expired.has($('#viewer').dataset.messageId))$('#viewer').close();if($('#voice-player').open&&expired.has($('#voice-player').dataset.messageId))$('#voice-player').close();vault.messages=vault.messages.filter(m=>!expired.has(m.id));for(const m of vault.messages)if(m.reply&&expired.has(m.reply.id))m.reply.text='Message disappeared';vault.outbox=vault.outbox.filter(m=>!m.expires||m.expires>now);return before!==vault.messages.length}
