async function viewOnce(id){if(openingMedia)return;openingMedia=true;try{if(!vault||$('#viewer').open)return;const current=vault,fence=pairGeneration;const original=vault.messages.find(m=>m.id===id);if(original?.expires&&original.expires<=Date.now()){prune();render();return}if(original)markSeen(original);const content=consumeGift(vault,id);if(!content)return;await save();if(vault!==current||fence!==pairGeneration||document.hidden)return;render();if(content.file){showMedia(content.file,{once:true,id});if(content.text)$('#viewer-content').append(el('p',content.text,'gift-text'))}else{$('#viewer-content').replaceChildren(el('div',content.text,'gift-text'));$('#save-viewer').hidden=true;$('#save-viewer').onclick=null;$('#viewer').dataset.messageId=id;$('#viewer').showModal()}$('#viewer').classList.add('unwrapping');giftDeadline=Date.now()+content.seconds*1000;const tick=()=>{const seconds=Math.max(0,Math.ceil((giftDeadline-Date.now())/1000));$('#viewer-caption').textContent=(content.remaining===null?'Closes in ':content.remaining>0?'Closes in ':'Vanishes in ')+seconds+'s'+(content.remaining===null?' · unlimited opens':content.remaining>0?' · '+content.remaining+' open left':' · close to erase now');if(!seconds)$('#viewer').close()};clearInterval(giftTimer);tick();giftTimer=setInterval(tick,200);control(content.remaining===0?{type:'opened',target:id}:{type:'read',targets:[{id,at:Date.now()}]}).catch(()=>toast('Opening receipt will send when connected'));}catch(e){toast(e.message)}finally{openingMedia=false}}
