async function restoreDeviceLogin(){if(!nativeRemember||restoring||vault)return;restoring=true;const generation=++loginGeneration;const check=()=>{if(generation!==loginGeneration)throw Object.assign(Error('Unlock interrupted'),{cancelled:true})};try{const raw=window.OnlyYoursNative.restoreLogin();if(!raw){const status=typeof window.OnlyYoursNative.savedLoginStatus==='function'?window.OnlyYoursNative.savedLoginStatus():'';if(status==='auth_required'&&Date.now()-lastUnlockRetry>30000&&typeof window.OnlyYoursNative.requestSavedUnlock==='function'){lastUnlockRetry=Date.now();window.OnlyYoursNative.requestSavedUnlock(true)}return}const saved=JSON.parse(raw);await resumeDeviceSession({unlockLocal:async()=>{const metadata=JSON.parse(localStorage.getItem('oy-vault')||'null');if(!metadata||saved.id!==metadata.id||saved.salt!==metadata.salt)throw Error('Use your password to unlock this device');const restoredKey=await crypto.subtle.importKey('raw',un64(saved.key),{name:'AES-GCM'},true,['encrypt','decrypt']);const restoredVault=await open(await readVault(),restoredKey);const restoredPrivate=await crypto.subtle.importKey('jwk',restoredVault.private,{name:'ECDH',namedCurve:'P-256'},false,['deriveKey']);check();salt=saved.salt;key=restoredKey;vault=restoredVault;token=saved.token;privateKey=restoredPrivate},openLocal:async()=>{check();$('#password').value='';if($('#gate').open)$('#gate').close();window.OnlyYoursNative.setSession(token);render();last=Date.now()},connect:async()=>{check();await refresh();check();render();startLive()},renew:async()=>{await drainPendingFile();return api('remember')},expired:async()=>{check();streamAbort?.abort();direct?.close();vault=key=token=privateKey=shared=me=null;gate();toast('Your saved session expired. Sign in once to renew it.')},offline:async error=>{check();if(error?.cancelled)throw error;await refresh({cachedOnly:true});check();render();$('#privacy-line').textContent='Offline · Your saved device login and history are available';startLive();await drainPendingFile()}})}catch(error){if(error?.cancelled||generation!==loginGeneration)return;vault=key=token=privateKey=shared=me=null;if(!$('#gate').open)gate();toast('Use your password once to refresh saved device access. Your encrypted history is unchanged.')}finally{restoring=false}}
window.addEventListener('onlyyours:unlocked',restoreDeviceLogin);
window.addEventListener('onlyyours:native-lock',()=>{if(vault)lock(false)});
$('#forget-login').onclick=async()=>{if(!nativeRemember)return;try{await api('logout')}catch{}window.OnlyYoursNative.forgetLogin();$('#remember').checked=false;lock();toast('Saved login removed. Your encrypted history stays on this device.')};
restoreDeviceLogin();

const reading=new Set();let readTimer;
const readObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{if(!vault||document.visibilityState!=='visible'||activeView!=='chat'||$('#gate').open||($('#call-dialog').open&&!$('#call-dialog').classList.contains('minimized'))||$('#burst').open||$('#viewer').open||$('#media-composer').open||$('#camera-dialog').open||$('#voice-recorder').open||$('#voice-player').open)return;for(const entry of entries)if(entry.isIntersecting&&entry.intersectionRatio>=.6){const id=entry.target.dataset.messageId;const m=vault.messages.find(x=>x.id===id&&!x.mine);if(m&&!m.readAt&&!m.once&&!m.gift){markSeen(m);reading.add(id)}}clearTimeout(readTimer);if(reading.size)readTimer=setTimeout(async()=>{if(!vault||!reading.size)return;const targets=[...reading].slice(0,100);for(const id of targets)reading.delete(id);try{await save();await control({type:'read',targets:targets.map(id=>({id,at:vault.messages.find(m=>m.id===id)?.readAt||Date.now()}))})}catch{}},120)},{root:$('#messages'),threshold:.6}):null;
function callState(state){if(['incoming','preparing'].includes(state.phase)&&$('#voice-recorder').open)voiceComposer.close();const d=$('#call-dialog');if(state.phase==='incoming'&&typeof window.OnlyYoursNative?.notifyIncomingCall==='function')window.OnlyYoursNative.notifyIncomingCall(state.id,!!state.video);else if(['connecting','connected','ended'].includes(state.phase)&&typeof window.OnlyYoursNative?.clearIncomingCall==='function')window.OnlyYoursNative.clearIncomingCall(state.id||callManager?.id||'');if(state.phase==='ended'){clearInterval(callClock);callStarted=null;callView.reset();if(vault)render();toast(state.detail);if(document.hidden&&vault)lock(false);return}if(!d.open){d.classList.remove('minimized');d.showModal()}$('#call-chat').disabled=['incoming','preparing'].includes(state.phase);$('#call-state').textContent=state.detail;$('#call-answer').hidden=state.phase!=='incoming';$('#call-mute').hidden=state.phase==='incoming';$('#call-camera').hidden=state.phase==='incoming';$('#call-camera').textContent=state.cameraLocal?'Camera off':'Turn video on';$('#call-camera').disabled=!!state.sharingLocal;$('#call-share').disabled=state.phase!=='connected';$('#call-share').textContent=state.sharingLocal?'Stop sharing':'Share screen';d.classList.toggle('screen-sharing',!!state.sharingLocal||!!state.sharingRemote);$('#local-video').hidden=!(state.cameraLocal||state.sharingLocal);$('#call-chat').textContent='Chat';$('#call-avatar').hidden=!!$('#remote-video').srcObject&&state.video;d.classList.toggle('audio-only',!state.video);if(state.phase==='connected'&&!callStarted){callStarted=Date.now();callClock=setInterval(()=>{const seconds=Math.floor((Date.now()-callStarted)/1000);$('#call-duration').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')},1000)}}
callManager=new LoveCall({history:handleCallHistory,isFinal:id=>hasEndedCall(vault,id),acquire:async(video,id)=>{const result=await acquireNativeCall(window.OnlyYoursNative,video,id,{visible:()=>document.visibilityState==='visible'});if(!result.background&&!result.browser){$('#call-dialog .call-note').textContent='Foreground call · keep this app open';toast(result.reason==='update-required'?'Update the Android app for reliable background calling. This call can continue while open.':result.reason==='permissions'?'Android denied background-call permission. Keep the app open for this call.':'Background calling is unavailable. Keep the app open for this call.')}},release:id=>{if(id&&typeof window.OnlyYoursNative?.finishCallSession==='function')window.OnlyYoursNative.finishCallSession(id)},signal:async data=>{if(!shared||!me?.partner||vault?.pendingDisconnect)throw Error('Connect with your person first');const pair=[me.id,me.partner].sort().join('|'),k=shared,epoch=me.epoch,bearer=token,fence=pairGeneration;const payload=JSON.stringify({...await seal({call:data},k,'signal|'+pair),notice:callNotice(data)});let sent=false;for(const delay of [0,500,1500,3500]){if(delay)await new Promise(r=>setTimeout(r,delay));if(fence!==pairGeneration)throw Error('Pairing ended');try{const response=await fetch('/api/signal',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+bearer},body:JSON.stringify({epoch,payload}),signal:AbortSignal.timeout(8000)});if(response.ok){sent=true;break}if([401,403,409].includes(response.status))throw Object.assign(Error('Pairing or login changed'),{permanent:true})}catch(error){if(error.permanent)throw error}}if(!sent)throw Error('Could not reach your person. Check the connection.');if(data.kind==='offer'&&!data.restart&&direct?.channel?.readyState!=='open')await control({type:'call-invite',call:data},60000)},state:callState,local:stream=>{$('#local-video').srcObject=stream},remote:stream=>{$('#remote-video').srcObject=stream;$('#call-avatar').hidden=!!stream&&!!(callManager.video||callManager.remoteCamera||callManager.remoteScreen);if(stream)$('#remote-video').play().catch(()=>{})}});
async function startCall(video){if(!shared||!me?.partner)return toast('Pair with your person first');try{$('#call-mute').textContent='Mute';$('#call-camera').textContent='Camera off';$('#call-duration').textContent='';const config=await getRtcConfig();callManager.iceServers=config.iceServers;$('#call-dialog .call-note').textContent=(config.hasRelay?'Encrypted call · relay available':'Direct call · no relay configured')+(typeof window.OnlyYoursNative?.beginCallSession==='function'?' · Background calling enabled':' · Keep this tab open');await callManager.start(video)}catch(e){if(e.cancelled)return;if($('#call-dialog').open)$('#call-dialog').close();toast(e.name==='NotAllowedError'?'Allow microphone/camera access to call':e.message)}}
$('#voice-call').onclick=()=>startCall(false);$('#video-call').onclick=()=>startCall(true);
$('#call-answer').onclick=async()=>{try{const config=await getRtcConfig();callManager.iceServers=config.iceServers;await callManager.answer()}catch(e){if(!e.cancelled)toast(e.message)}};
$('#call-end').onclick=$('#call-close').onclick=()=>callManager.end();
$('#call-dialog').addEventListener('cancel',e=>{e.preventDefault();callManager.end()});
$('#call-mute').onclick=()=>{$('#call-mute').textContent=callManager.toggleAudio()?'Mute':'Unmute'};
$('#call-camera').onclick=async()=>{try{$('#call-camera').disabled=true;await callManager.toggleVideo()}catch(error){toast(error.name==='NotAllowedError'?'Allow camera access to turn video on':error.message)}finally{$('#call-camera').disabled=!!callManager.screenCapture}};

window.addEventListener('onlyyours:affection-closed',()=>{if(vault)render()});

function personName(){return vault?.profile?.personName||'Your person'}
function avatarFor(name,icon){if(icon&&icon!=='initials')return icon;return name?name.trim().split(/\s+/).map(s=>Array.from(s)[0]||'').slice(0,2).join('').toUpperCase():'♡'}
function updateProfile(){if(!vault)return;const p=vault.profile||{};$('#partner-title').textContent=personName();$('#call-person-name').textContent=personName();$('#chat-avatar').textContent=avatarFor(p.personName,p.personIcon);$('#call-avatar').textContent=avatarFor(p.personName,p.personIcon);$('#person-avatar').textContent=avatarFor(p.personName,p.personIcon);$('#self-avatar').textContent=avatarFor(p.selfName,p.selfIcon);$('#couple-names').replaceChildren(document.createTextNode(p.selfName||'You'),el('em',' & '),document.createTextNode(personName()));if(document.activeElement?.closest('#profile-form'))return;$('#self-name').value=p.selfName||'';$('#person-name').value=p.personName||'';$('#self-icon').value=p.selfIcon||'initials';$('#person-icon').value=p.personIcon||'initials'}
$('#profile-form').onsubmit=async e=>{e.preventDefault();if(!vault)return;vault.profile={selfName:$('#self-name').value.trim().slice(0,32),personName:$('#person-name').value.trim().slice(0,32),selfIcon:$('#self-icon').value,personIcon:$('#person-icon').value};await save();document.activeElement?.blur();updateProfile();toast('Names and avatars saved on this device')};
$('#person-avatar-button').onclick=()=>{document.querySelector('[data-view="settings"]').click();$('#person-name').focus()};

async function importEncryptedDevice(input){const transfer=validateTransfer(input);const current=JSON.parse(localStorage.getItem('oy-vault')||'null');const decision=importDecision(current,transfer);if(decision==='import'){await writeVault(transfer.box);localStorage.setItem('oy-vault',JSON.stringify(transfer.metadata));if(transfer.theme)localStorage.setItem('oy-theme',transfer.theme)}return decision}
async function importStagedDevice(){if(typeof window.OnlyYoursNative?.stagedVaultMigration!=='function')return;try{const raw=window.OnlyYoursNative.stagedVaultMigration();if(!raw)return;await importEncryptedDevice(JSON.parse(raw));window.OnlyYoursNative.completeVaultMigration()}catch(e){toast(e.message||'Could not move this device vault. The original history is unchanged.')}}
$('#import-vault-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(vault)throw Error('Lock the app before importing a device backup');if(f.size>65000000)throw Error('This backup is too large');const result=await importEncryptedDevice(JSON.parse(await f.text()));if(result==='keep-current')toast('This device already has that account; current history was kept');else toast('Encrypted device imported. Use your existing password to unlock.');mode='unlock';if($('#gate').open)$('#gate').close();gate()}catch(err){toast(err.message)}e.target.value=''};

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&nativeRemember&&!vault){if(typeof window.OnlyYoursNative.requestSavedUnlock==='function')window.OnlyYoursNative.requestSavedUnlock(false);else restoreDeviceLogin()}});

setInterval(()=>{if(vault&&document.visibilityState==='visible')sync().catch(()=>{})},3000);

$('#call-data-saver').onclick=async()=>{$('#call-data-saver').textContent=await callManager.toggleDataSaver()?'Data saver on':'Data saver off'};

window.addEventListener('onlyyours:end-call',event=>{const action=nativeCallAction(event.detail,callManager?.id);if(action==='end')callManager.end(event.detail.reason==='notification'?'Call ended using the notification':'Call ended when the app was closed');else if(action==='foreground-only'){if(document.hidden)callManager.end('Android stopped background calling. Reopen the app to call.');else{$('#call-dialog .call-note').textContent='Foreground call · keep this app open';toast('Background service stopped. Your call can continue while this app stays open.')}}});

let localDeleteIds=[];
function requestLocalDelete(ids){if(!vault)return;localDeleteIds=[...ids];$('#delete-local-title').textContent=ids.length===1?'Delete this message for you?':'Clear chat on this device?';$('#delete-local-dialog').showModal()}
$('#clear-local-chat').onclick=()=>{if(!vault?.messages.length)return toast('Your chat is already empty');requestLocalDelete(vault.messages.map(m=>m.id))};
$('#cancel-local-delete').onclick=()=>$('#delete-local-dialog').close();
$('#confirm-local-delete').onclick=async()=>{if(!vault)return;const ids=localDeleteIds;$('#delete-local-dialog').close();if(ids.includes($('#viewer').dataset.messageId)&&$('#viewer').open)$('#viewer').close();deleteLocalMessages(vault,ids);if(reply&&ids.includes(reply.id)){reply=null;$('#reply-preview').hidden=true}for(const id of ids)reading.delete(id);try{await save();render();toast('Deleted from this device only')}catch(e){toast(e.message)}};

function beginReply(message){if(!vault||!vault.messages.some(m=>m.id===message.id))return;reply={id:message.id,text:message.once?'View-once gift':message.disappearAfter?'Disappearing message':message.text||message.file?.name||'Attachment'};$('#reply-preview span').textContent=reply.text;$('#reply-preview').hidden=false;$('#text').focus({preventScroll:true})}
bindSwipeReply($('#messages'),id=>{const message=vault?.messages.find(m=>m.id===id);if(message)beginReply(message)},{onGesture:active=>{swipeInProgress=active;if(!active&&renderAfterSwipe){renderAfterSwipe=false;render()}},onReady:()=>navigator.vibrate?.(10)});

let flushingCallResults=false;
function handleCallHistory(event){if(!vault)return;const message=recordCall(vault,event);if(!message)return;if(event.endedAt&&event.direction==='outgoing'){vault.pendingCallResults||=[];if(!vault.pendingCallResults.some(x=>x.call.id===event.id))vault.pendingCallResults.push({call:message.call,partner:me?.partner,epoch:me?.epoch})}save().then(()=>flushCallResults()).catch(()=>{});render()}
async function flushCallResults(){if(flushingCallResults||!vault||!shared||!me?.partner)return;flushingCallResults=true;const current=vault;try{vault.pendingCallResults=(vault.pendingCallResults||[]).filter(x=>x.partner===me.partner&&x.epoch===me.epoch);for(const entry of [...vault.pendingCallResults]){await control({type:'call-result',call:entry.call},7*86400000);if(vault!==current)return;vault.pendingCallResults=vault.pendingCallResults.filter(x=>x!==entry);await save()}}finally{flushingCallResults=false}}

const callView=createCallView($('#call-dialog'),{onChat:()=>{document.querySelector('[data-view="chat"]').click();if(vault)render();$('#text').focus({preventScroll:true})},onExpand:()=>$('#text').blur()});
$('#call-chat').onclick=()=>callView.minimize();$('#call-expand').onclick=()=>callView.expand();

let notificationCallAction=null;
function readNotificationCallAction(){if(typeof window.OnlyYoursNative?.consumeCallAction!=='function')return;try{const raw=window.OnlyYoursNative.consumeCallAction();if(raw)notificationCallAction=JSON.parse(raw)}catch{}}
async function applyNotificationCallAction(){readNotificationCallAction();const action=notificationCallAction;if(!action)return;if(callManager?.id===action.id&&callManager.phase==='incoming'){notificationCallAction=null;if(action.action==='answer')await callManager.answer();else if(action.action==='decline')await callManager.end('Call declined')}else if(Date.now()-action.at>60000){notificationCallAction=null;toast('That call is no longer ringing')}}
window.addEventListener('onlyyours:notification-action',()=>{readNotificationCallAction();sync().catch(()=>{})});window.addEventListener('onlyyours:unlocked',()=>{readNotificationCallAction();sync().catch(()=>{})});

$('#call-share').onclick=async()=>{try{if(callManager.screenCapture)await callManager.stopScreenShare();else{await callManager.startScreenShare(captureScreen);toast('Screen sharing started. Switch to the app you want to show. Your private chat stays hidden on Android.')}}catch(error){if(!error.cancelled)toast(error.message)}};



document.addEventListener('visibilitychange',()=>{if(document.hidden&&$('#viewer').open)$('#viewer').close()});

const giftMenu=bindGiftMenu({form:$('#composer'),input:$('#text'),menu:$('#send-options'),onEmpty:()=>toast('Write your gift message first'),onGift:(text,giftDuration,playLimit)=>sendMessage(text,undefined,{gift:true,playLimit,clearDraft:true,giftDuration}).catch(e=>toast(e.message))});

const voicePlayer=createVoicePlayer($('#voice-player'));
const voiceComposer=bindVoiceComposer({dialog:$('#voice-recorder'),onFile:sendSelectedFile,onError:e=>toast(e.message),canRecord:()=>{if(!vault||!me?.partner){toast('Pair with your person first');return false}if(callManager?.id){toast('Finish your call before recording a voice message');return false}return true}});
$('#voice-message').onclick=()=>voiceComposer.open();
async function playVoiceMessage(id){if(openingVoice)return;openingVoice=true;try{if(!vault||$('#voice-player').open)return;const current=vault,fence=pairGeneration,m=vault.messages.find(m=>m.id===id);if(!m?.file||!m.file.type.startsWith('audio/'))return;if(m.expires&&m.expires<=Date.now()){prune();render();return}let content;if(m.once){markSeen(m);content=consumeGift(vault,id);if(!content)return;await save()}else content={file:m.file,remaining:null,limit:0};if(vault!==current||fence!==pairGeneration||document.hidden)return;voicePlayer.open(new Blob([un64(content.file.data)],{type:content.file.type}),content);$('#voice-player').dataset.messageId=id;render();if(m.once)control(content.remaining===0?{type:'opened',target:id}:{type:'read',targets:[{id,at:m.readAt||Date.now()}]}).catch(()=>{})}catch(e){toast(e.message)}finally{openingVoice=false}}
